export function getVocabulary(id) {
  return vocabulary[id] || null;
}

export function vocabularyForTopic(topic) {
  return (vocabularyByTopic[topic] || [])
    .map((id) => vocabulary[id])
    .filter(Boolean);
}

/**
 * Filter topic vocabulary by Learn/Practice scope.
 * No hard unlocks — callers pass curriculum-appropriate areas / introduced_by prefixes.
 *
 * @param {string} topic
 * @param {{
 *   areas?: string[],
 *   introducedBy?: string[],
 *   maxLevel?: number,
 *   activeOnly?: boolean,
 * }} [scope]
 */
export function vocabularyForScope(topic, scope = {}) {
  let items = vocabularyForTopic(topic).filter((item) => {
    if (scope.activeOnly === false) return true;
    return !item.status || item.status === "active";
  });
  const areas = Array.isArray(scope.areas)
    ? scope.areas.filter(Boolean)
    : null;
  if (areas?.length) {
    items = items.filter((item) => item.area && areas.includes(item.area));
  }
  const introducedBy = Array.isArray(scope.introducedBy)
    ? scope.introducedBy.filter(Boolean)
    : null;
  if (introducedBy?.length) {
    items = items.filter((item) =>
      (item.introduced_by || []).some((cid) =>
        introducedBy.some(
          (want) => cid === want || String(cid).startsWith(want + ".")
        )
      )
    );
  }
  if (scope.maxLevel != null && Number.isFinite(Number(scope.maxLevel))) {
    const max = Number(scope.maxLevel);
    items = items.filter(
      (item) => item.level == null || Number(item.level) <= max
    );
  }
  return items;
}

/** Stable Learn order: level → surface (no shuffle). */
export function vocabularyLearnOrder(items) {
  return [...(items || [])].sort((a, b) => {
    const la = a.level == null ? 99 : Number(a.level);
    const lb = b.level == null ? 99 : Number(b.level);
    if (la !== lb) return la - lb;
    return String(a.surface || "").localeCompare(String(b.surface || ""), "de");
  });
}

/** Map a Numbers curriculum topic id to a Vocabulary area id. */
export function vocabAreaForCurriculumTopic(topicId) {
  return curriculumTopicToVocabArea[topicId] || null;
}
